sys_security_acl.script:
var userId = gs.getUserID();
if (current.assigned_to == userId) { answer = true; return; }
if (current.opened_by == userId) { answer = true; return; }
var grpId = current.getValue('assignment_group');
if (grpId) {
    var grp = new GlideRecord('sys_user_grmember');
    grp.addQuery('group', grpId);
    grp.addQuery('user', userId);
    grp.query();
    if (grp.hasNext()) { answer = true; return; }
}
answer = false;
